// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAvailability Free and taken slots for one sport on one day
	// (GET /v1/availability)
	GetAvailability(ctx context.Context, request GetAvailabilityRequestObject) (GetAvailabilityResponseObject, error)
	// GetBooking A booking's current state, for the player's confirmation screen
	// (GET /v1/bookings/{reference})
	GetBooking(ctx context.Context, request GetBookingRequestObject) (GetBookingResponseObject, error)
	// PlaceHold Hold a court for 10 minutes while the player pays the deposit
	// (POST /v1/holds)
	PlaceHold(ctx context.Context, request PlaceHoldRequestObject) (PlaceHoldResponseObject, error)
	// ListOwnerBookings Every booking that occupies a court on one day, for the schedule board
	// (GET /v1/owner/bookings)
	ListOwnerBookings(ctx context.Context, request ListOwnerBookingsRequestObject) (ListOwnerBookingsResponseObject, error)
	// RescheduleBooking Move a booking to another court or time
	// (PATCH /v1/owner/bookings/{id})
	RescheduleBooking(ctx context.Context, request RescheduleBookingRequestObject) (RescheduleBookingResponseObject, error)
	// ChangeBookingStatus Confirm payment at the desk, cancel, or mark a no-show
	// (POST /v1/owner/bookings/{id}/status)
	ChangeBookingStatus(ctx context.Context, request ChangeBookingStatusRequestObject) (ChangeBookingStatusResponseObject, error)
	// LogOut End the owner session
	// (DELETE /v1/owner/session)
	LogOut(ctx context.Context, request LogOutRequestObject) (LogOutResponseObject, error)
	// LogIn Start an owner session; the token is set as an HttpOnly cookie
	// (POST /v1/owner/session)
	LogIn(ctx context.Context, request LogInRequestObject) (LogInResponseObject, error)
	// CreateWalkIn Book a court for a customer at the desk
	// (POST /v1/owner/walk-ins)
	CreateWalkIn(ctx context.Context, request CreateWalkInRequestObject) (CreateWalkInResponseObject, error)
	// ReceivePaymentNotification The payment provider reports a deposit transaction change
	// (POST /v1/payments/notifications)
	ReceivePaymentNotification(ctx context.Context, request ReceivePaymentNotificationRequestObject) (ReceivePaymentNotificationResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

